import os, re

def load_demos():
    session_dir = os.environ.get('RLM_SESSION_DIR', '')
    if not session_dir:
        print("Session dir not found, checking environment")
        print("Env keys:", [k for k in dir(__import__('os')).lower() if not k.startswith('_')])

