    if not session_file:
        print(f"Session dir: {session_dir}")
        return {}

    try:
        with open(session_file, 'r') as f:
            content = f.read()
    except FileNotFoundError:  # Try to find the session
        print(f"File not found: {session_file}")
        return {}

    demos = {}
    for match in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', content):
        key = match.group(1)
        r, c = int(match.group(2)), int(match.group(3))

        lines = []
        remaining = content[match.end():]
